{'name': 'Nordstrom Ebar Artisan Coffee', 'address': '17 W Canon Perdido St', 'city': 'Santa Barbara', 'state': 'CA', 'categories': 'Nightlife, Food, Coffee & Tea, Coffeeshops, Internet Cafes', 'hours': {'Monday': '0:0-0:0', 'Tuesday': '7:30-20:0', 'Wednesday': '7:30-20:0', 'Thursday': '7:30-20:0', 'Friday': '7:30-20:0', 'Saturday': '9:0-20:0', 'Sunday': '10:0-19:0'}, 'attributes': {'BusinessParking': {'garage': False, 'street': False, 'validated': False, 'lot': False, 'valet': False}, 'RestaurantsReservations': None, 'OutdoorSeating': True, 'WiFi': 'free', 'RestaurantsTakeOut': True, 'RestaurantsGoodForGroups': True, 'Music': None, 'Ambience': {'romantic': False, 'intimate': False, 'classy': False, 'hipster': False, 'divey': False, 'touristy': False, 'trendy': False, 'upscale': False, 'casual': False}}, 'business_stars': 4.5, 'review_info': [{'review_stars': 5.0, 'review_date': '2019-04-29 14:08:08', 'review_text': "Nordstrom Ebars have surprisingly good coffee and you shouldn't discount it just because its part of Nordstrom. Great to have options beside Starbucks."}, {'review_stars': 5.0, 'review_date': '2019-01-03 20:30:41', 'review_text': 'The girls who waited on me were so sweet and friendly it was unreal!  Like they have been your friend forever.  Matti took my order and Sophia was so friendly too.  I just like to review when people are so above and beyond, the energy was wonderful in there.'}, {'review_stars': 4.0, 'review_date': '2018-11-18 18:50:57', 'review_text': 'Thanks for going like on the flavoring for me by special request and I love the original seasonal options here. Super convenient spot to grab coffee on my way to shop the mall!'}]}
